import 'auth_models.dart';
class RouteGuard { const RouteGuard(); String? redirect(AuthSession session,String location) { if(session.status==AuthStatus.suspended)return location=='/account-status'?null:'/account-status'; if(session.status==AuthStatus.sessionExpired)return '/auth/session-expired'; final protected=location.startsWith('/profile')||location.startsWith('/seller/')||location.startsWith('/admin/'); if(protected&&session.status!=AuthStatus.loggedIn){if(location=='/seller/login'||location=='/admin/login')return null;return '/auth/login';} if(location.startsWith('/admin/')&&session.role!=UserRole.admin&&session.role!=UserRole.superAdmin)return '/forbidden'; if(location.startsWith('/admin/super')&&session.role!=UserRole.superAdmin)return '/forbidden'; if(location.startsWith('/seller/')&&session.role!=UserRole.seller)return '/forbidden'; return null; } }
